// Generated by esquadro: do not edit. Duplicating a record: the form to
// create one starts with its values (what it is called gets " (copy)"), and
// nothing is saved until the person saves.
import { useNavigate } from "@tanstack/react-router"
import { t } from "./i18n.ts"
import type { Rec, ResourceMeta } from "./meta.ts"

/** The values of a copy of a record: its fields, without what the API sets. */
export function copyOf(meta: ResourceMeta, record: Rec): Record<string, unknown> {
  const out: Record<string, unknown> = {}
  for (const f of Object.values(meta.fields)) {
    if (f.readOnly || record[f.name] === null || record[f.name] === undefined) continue
    out[f.name] = record[f.name]
  }
  if (typeof out[meta.title] === "string") out[meta.title] = `${out[meta.title]} ${t("copySuffix")}`
  return out
}

/** Opens the form to create a copy of a record. */
export function useDuplicate(meta: ResourceMeta) {
  const navigate = useNavigate()
  return (record: Rec) => navigate({ to: `/${meta.name}/new` as never, state: { copy: copyOf(meta, record) } as never })
}
